import type { Character } from "../models/character";
import type { Ability } from "../models/ability";
import type { Location } from "../models/location";
import { nextAiNoteId, type AiNote, type AiNoteSource } from "../models/aiNote";
import { clampSummary } from "./summaryLimit";

/**
 * 作者がパネル上で書き換えた内容をレコードへ反映する。
 *
 * 反映するのは作者が触れる項目だけにする。
 * 登場話数や抽出根拠のような「本文から機械的に求まる値」を
 * 画面から編集できるようにすると、次の抽出で戻されて混乱するため。
 *
 * **作者が自分で書き換えたレコードは autoGenerated を false にする。**
 * 作者が確定させたものはAIの再抽出で上書きしない、という
 * 既存の約束（CLAUDE.md）に合わせるため。
 *
 * ただし**AIの提案をそのまま採用した場合は false にしない**（`EditOptions`）。
 * 中身はAIが書いたもので、作者が確定させた記述ではない。
 * false にすると、その人物は以後の抽出から締め出され、
 * 書き進めても情報が増えなくなる。
 */

export interface RecordEdits {
  name?: string;
  /** 一覧に出す短い紹介。50字を超える分はコード側で切る */
  summary?: string;
  affiliation?: string;
  reading?: string;
  /** 読点・改行区切りの別名 */
  aliases?: string;
  role?: string;
  personality?: string;
  appearance?: string;
  category?: string;
  description?: string;
  cost?: string;
  limitation?: string;
  region?: string;
  authorNotes?: string;
  exportNote?: string;
}

export class SettingsEditError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "SettingsEditError";
  }
}

export interface EditOptions {
  /**
   * 作者が自分で書いた内容か。
   *
   * true なら `autoGenerated` を false にし、以後の抽出で上書きされなくする。
   *
   * **AIの提案をそのまま採用した場合は false にする。** 中身はAIが書いたもので、
   * 作者が確定させた記述ではない。true にすると、その人物は以後の抽出から
   * 締め出され、書き進めても情報が増えなくなる。
   * 一度でも作者が確定させた記録は、AIの反映では取り消さない。
   */
  authorConfirmed?: boolean;
}

/** 反映後の autoGenerated を決める */
function nextAutoGenerated(
  current: boolean,
  options: EditOptions | undefined
): boolean {
  if (options?.authorConfirmed === false) return current;
  return false;
}

export function applyCharacterEdits(
  character: Character,
  edits: RecordEdits,
  options?: EditOptions
): Character {
  return {
    ...character,
    name: editedName(character.name, edits.name),
    // 作者が書いた紹介文も長さは揃える。一覧の見た目が崩れるため
    summary: clampSummary(nullableText(character.summary, edits.summary)),
    affiliation: nullableText(character.affiliation, edits.affiliation),
    reading: nullableText(character.reading, edits.reading),
    aliases: editedAliases(character.aliases, edits.aliases),
    role: nullableText(character.role, edits.role),
    personality: nullableText(character.personality, edits.personality),
    appearance: nullableText(character.appearance, edits.appearance),
    authorNotes: plainText(character.authorNotes, edits.authorNotes),
    exportNote: plainText(character.exportNote, edits.exportNote),
    autoGenerated: nextAutoGenerated(character.autoGenerated, options),
  };
}

export function applyAbilityEdits(
  ability: Ability,
  edits: RecordEdits,
  options?: EditOptions
): Ability {
  return {
    ...ability,
    name: editedName(ability.name, edits.name),
    summary: clampSummary(nullableText(ability.summary, edits.summary)),
    reading: nullableText(ability.reading, edits.reading),
    aliases: editedAliases(ability.aliases, edits.aliases),
    category: nullableText(ability.category, edits.category),
    description: nullableText(ability.description, edits.description),
    cost: nullableText(ability.cost, edits.cost),
    limitation: nullableText(ability.limitation, edits.limitation),
    authorNotes: plainText(ability.authorNotes, edits.authorNotes),
    exportNote: plainText(ability.exportNote, edits.exportNote),
    autoGenerated: nextAutoGenerated(ability.autoGenerated, options),
  };
}

export function applyLocationEdits(
  location: Location,
  edits: RecordEdits,
  options?: EditOptions
): Location {
  return {
    ...location,
    name: editedName(location.name, edits.name),
    summary: clampSummary(nullableText(location.summary, edits.summary)),
    reading: nullableText(location.reading, edits.reading),
    aliases: editedAliases(location.aliases, edits.aliases),
    region: nullableText(location.region, edits.region),
    description: nullableText(location.description, edits.description),
    authorNotes: plainText(location.authorNotes, edits.authorNotes),
    exportNote: plainText(location.exportNote, edits.exportNote),
    autoGenerated: nextAutoGenerated(location.autoGenerated, options),
  };
}

/** aiNotes を持つレコードの共通形 */
interface WithAiNotes {
  aiNotes: AiNote[];
}

export interface NewAiNote {
  topic: string;
  text: string;
  model: string;
  source: AiNoteSource;
}

/**
 * 承認された掘り下げメモを追記する。
 * 既存のメモは並べ替えず、末尾に足すだけにする。
 */
export function appendAiNote<T extends WithAiNotes>(
  record: T,
  note: NewAiNote,
  now: Date = new Date()
): T {
  const text = note.text.trim();
  if (!text) {
    throw new SettingsEditError("追記する内容が空です。");
  }
  const appended: AiNote = {
    id: nextAiNoteId(record.aiNotes),
    createdAt: now.toISOString(),
    topic: note.topic.trim(),
    text,
    model: note.model,
    source: note.source,
  };
  return { ...record, aiNotes: [...record.aiNotes, appended] };
}

export function removeAiNote<T extends WithAiNotes>(record: T, noteId: string): T {
  return {
    ...record,
    aiNotes: record.aiNotes.filter((note) => note.id !== noteId),
  };
}

/**
 * 名前は空にできない。
 * 空のまま保存を通すとファイル名がIDだけになり、
 * 作者がGitの差分で何の変更か判別できなくなる。
 */
function editedName(current: string, edited: string | undefined): string {
  if (edited === undefined) return current;
  const value = edited.trim();
  if (!value) {
    throw new SettingsEditError("名前は空にできません。");
  }
  return value;
}

/** 空欄は「未設定」を意味する。空文字ではなく null で持つ */
function nullableText(
  current: string | null,
  edited: string | undefined
): string | null {
  if (edited === undefined) return current;
  const value = edited.trim();
  return value ? value : null;
}

/** authorNotes / exportNote は空文字を許す（null にしない） */
function plainText(current: string, edited: string | undefined): string {
  if (edited === undefined) return current;
  return edited.trim();
}

/** 読点・改行・カンマのどれで区切っても同じように扱う */
export function editedAliases(
  current: string[],
  edited: string | undefined
): string[] {
  if (edited === undefined) return current;
  const parts = edited
    .split(/[、,\n]/)
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
  return [...new Set(parts)];
}
